#!/usr/bin/env python3
"""rc.1 fix pass, record-level findings (D-DATA; ADR-0032). Idempotent: a second run changes nothing.

  m5   Five X1 successors whose provenance did not name the v1 key they succeed (3.4.1, 3.4.4 twice, 5.3.3, 5.5.5) get
       the derivedFrom entry their disposition implies (merged-from for move-to-tools remainders and merges,
       split-from for splits; AUTHORING_GUIDE §6). X1 is then regenerated by scripts/migrate_v1.py.
  m6   A declared L5 without an L5 anchor contradicts SPEC §8.2 rule 2 (L5 only where SME panels confirm strategic
       demand): levelSpan.max becomes the highest anchored level. Every authored competency states levelSpanBasis
       (anchored | declared); knowledge areas, whose spans are not indicator-anchored, are `declared`.
  m8   Self-coded OBS-4 carries no information (98.8% are 3): obs4 becomes null until humans code it, and the agent's
       code is kept as obs4Draft {value, raterType llm, raterId, codedOn}.
  m10  State class records claimed hash pinning with sha256 null: storage becomes url-only (nothing was hashed).
Run: python3 -I docs/build/rc1-fix/fix_records.py   Licence: Apache-2.0.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import rc1lib as R  # noqa: E402

L = R.L
ORDER = ["A", "L1", "L2", "L3", "L4", "L5"]
M5 = {  # successor -> [(v1 key, relation)] (docs/decisions/v1_disposition.csv; data-method review m5)
    "emst:core/CMP-3WFPTJ9": [("v1:3.4.1", "merged-from"), ("v1:3.4.4", "merged-from")],   # SC-C10, durable remainder
    "emst:core/CMP-CZZ31P2": [("v1:3.4.4", "merged-from")],                               # DB-C26, durable remainder
    "emst:core/CMP-8QWCQ3R": [("v1:5.3.3", "split-from")],                                # DB-C50, core Section 106
    "emst:core/CMP-5NFAM97": [("v1:5.5.5", "merged-from")],                               # v1:5.3.4-A
}
M5_NOTE = "successor named by the v1 disposition; lineage added in the rc.1 fix pass (ADR-0032; review m5)"
OBS4_NOTE = {"en": "Self-coded by the authoring agent; IO human double-coding pending (ADR-0032; review m8). Never read as obs4."}
URL_ONLY_NOTE = ("Verbatim text not stored in CC0 files (reuse terms unverified). url-only: the document was read at the URL "
                 "on the retrieved date but not hashed, so no version is pinned (ADR-0032; review m10).")


def fix_m5(rec):
    adds = M5.get(rec.get("id"))
    if not adds:
        return None
    prov = dict(rec["provenance"])
    df = list(prov.get("derivedFrom") or [])
    have = {d.get("v1Key") for d in df}
    for key, rel in adds:
        if key not in have:
            df.append({"v1Key": key, "v1Code": key[3:], "relation": rel, "note": M5_NOTE})
    prov["derivedFrom"] = df
    rec["provenance"] = prov
    return rec


def fix_m6(rec):
    if rec.get("validationStatus") == "seed-v1" or rec.get("status") in ("superseded", "withdrawn"):
        return None
    span = dict(rec.get("levelSpan") or {})
    if not span:
        return None
    anchored = [lv.get("level") for lv in rec.get("levels") or [] if isinstance(lv, dict) and lv.get("indicators")]
    anchored = sorted({a for a in anchored if a in ORDER}, key=ORDER.index)
    if rec.get("competencyType") == "knowledge-area" or not anchored:
        basis = "declared"
    else:
        if span.get("max") == "L5" and "L5" not in anchored:
            span["max"] = anchored[-1]
            rec["levelSpan"] = span
            notes = list(rec.get("changeNote") or [])
            entry = {"release": "2.0.0-rc.1", "note": {"en": f"levelSpan.max L5 -> {anchored[-1]}: L5 is defined only where SME "
                                                             "panels confirm strategic demand (SPEC §8.2 rule 2; ADR-0032; review m6)."}}
            if entry not in notes:
                notes.append(entry)
            rec["changeNote"] = notes
        lo, hi = ORDER.index(span["min"]), ORDER.index(span["max"])
        need = [x for x in ORDER[lo:hi + 1] if x != "A"]
        basis = "anchored" if all(x in anchored for x in need) else "declared"
    if rec.get("levelSpanBasis") == basis:
        return rec
    return R.insert_after(rec, "levelSpan", "levelSpanBasis", basis)


def fix_m8(rec):
    if rec.get("validationStatus") == "seed-v1" or not isinstance(rec.get("obs4"), int):
        return None
    prov = rec.get("provenance") or {}
    agents = [a for a in prov.get("agent") or [] if a.startswith("emstagent:")] or ["emstagent:unknown-authoring-agent"]
    if prov.get("method") != "llm-assisted":
        raise SystemExit(f"{rec['id']}: obs4 not coded by an LLM-assisted author ({prov.get('method')}); review by hand")
    draft = {"value": rec["obs4"], "raterType": "llm", "raterId": agents[0],
             "codedOn": str(prov.get("generatedAt", R.TODAY))[:10], "note": OBS4_NOTE}
    rec["obs4"] = None
    return R.insert_after(rec, "obs4", "obs4Draft", draft)


def fix_m10(rec):
    changed = False
    for k in ("workDescriptionText", "mqText"):
        v = rec.get(k)
        if isinstance(v, dict) and v.get("storage") == "hash-and-url" and not v.get("sha256"):
            v = {kk: vv for kk, vv in v.items() if kk != "sha256"}
            v["storage"] = "url-only"
            v["note"] = URL_ONLY_NOTE
            rec[k] = v
            changed = True
    return rec if changed else None


def main():
    n = {"m5": 0, "m6": 0, "m8": 0, "m10": 0}
    for loc, rec in R.records({"Competency", "Indicator", "StateClassRecord"}):
        if loc.path.suffix != ".yaml":
            continue
        typ = rec["type"]
        fns = {"Competency": [("m5", fix_m5), ("m6", fix_m6)], "Indicator": [("m8", fix_m8)],
               "StateClassRecord": [("m10", fix_m10)]}[typ]
        for tag, fn in fns:
            if R.edit_yaml(loc.path, fn):
                n[tag] += 1
    print("records changed by finding:", n)
    R.summary("fix_records")


if __name__ == "__main__":
    main()
